		private void CreatePointDatas() {
			if (gmsMasterData == null)
				return;

			maxPointNum = gmsMasterData.Points.Length;
			GMSWork.EmitLog(string.Format("Total PointNum : {0}", maxPointNum));
			GMSPointDataModel[] pointDatas = new GMSPointDataModel[maxPointNum];
			MessageTextParseDataModel textDataModel = gmsMsgFile.GetTextDataModel(GMSDataConstants.POINT_LABEL_NAME);
			for (int i = 0; i < maxPointNum; i++)
			{
				GMSMasterData.SheetPoints point = gmsMasterData.Points[i];
				GMSPointDataModel pointData = new GMSPointDataModel();
				MessageWordSetHelper.SetDigitWord(0, point.id);
				textDataModel.ApplyFormat(true);
				string pointTitle = textDataModel.GetAllText();
				pointData.CreateData(point.index, pointTitle, point.point.normalized * CalcEarthRadius());
				pointDatas[i] = pointData;
				textDataModel.Dispose();
			}
			dataContainer.SetPointDatas(pointDatas);
			nowTotalPutPointNum = FirstCalcPutPointNum();
			coroutineCreatePointHistoryData = SmartPoint.AssetAssistant.Sequencer.Start(IE_CreatePointHistoryData());
		}
		private int FirstCalcPutPointNum() {
			int putCount = 0;
			for (int i = 0; i < maxPointNum; i++)
			{
				GMS_POINT_HISTORY_DATA[] historyDatas = PlayerWork.gmsData.pointDatas[i].historyDatas;
				for (int j = 0; j < historyDatas.Length; j++)
				{
					if (historyDatas[j].sendMonsNo != 0)
					{
						putCount++;
						break;
					}
				}
			}
			GMSWork.EmitLog(string.Format("User Put Count [{0}]", putCount));
			return putCount;
		}
		private global::System.Collections.IEnumerator IE_CreatePointHistoryData() {
