			for (int i = 0; i < maxPointNum; i++)
			{
				GMSPointDataModel pointData = GetPointDataModelByIndex(i);
				GMS_POINT_HISTORY_DATA[] historyDatas = PlayerWork.gmsData.pointDatas[i].historyDatas;
				for (int j = 0; j < historyDatas.Length; j++)
				{
					PointHistoryDataModel newHistoryData = CreatePointHistoryDataModelByHistoryData(historyDatas[j], PlayerWork.gmsExtData[GMSWork.CalcPointExtDataIndex(i, j)]);
					if (newHistoryData != null)
						pointData.AddHistoryData(newHistoryData);
				}
				completePointCount++;
				if (completePointCount % GMSDataConstants.CREATE_POINT_DATA_SPAN == 0)
					yield return null;
			}
			ResetData();
			msgManagerPtr.ClearTagWordParams();
			coroutineCreatePointHistoryData = null;
			bIsReady = true;
		}
