		public string CreatePointMonsVoiceEvent(int pointIndex) {
			GMSPointDataModel pointData = GetPointDataModelByIndex(pointIndex);
			if (pointData == null || !pointData.HasData)
				return string.Empty;

			voiceEventSb.Clear();
			PointHistoryDataModel historyData = pointData.GetMarkHistoryData();
			int voiceNo;
			if (historyData.ReceiveMonsNo == MonsNo.IIBUI)
				voiceNo = GetDataValue(ValueDataIndex.iibuiVoiceNo);
			else if (historyData.ReceiveMonsNo == MonsNo.PIKATYUU)
				voiceNo = GetDataValue(ValueDataIndex.pikcaVoiceNo);
			else
				voiceNo = GetDataValue(ValueDataIndex.monsVoiceNo);
			voiceEventSb.Append(Utils.GetVoiceID(historyData.ReceiveMonsNo, (int)historyData.ReceiveFormNo, voiceNo));
			GMSWork.EmitLog(string.Format("Created Voice EventName : [{0}]", voiceEventSb));
			return voiceEventSb.ToString();
		}
		private global::Dpr.GMS.PointHistoryDataModel CreatePointHistoryDataModelByHistoryData(global::DPData.GMS_POINT_HISTORY_DATA hitsoryData, global::DPData.GMS_POINT_HISTORY_EXT_DATA extData) {
			IntermediatePointData data = GMSWork.ConvertPointData(hitsoryData, extData);
			if (data == null)
				return null;

			return CreateHistoryDataModel(data);
		}
		private global::Dpr.GMS.PointHistoryDataModel CreateHistoryDataModel(global::Dpr.GMS.IntermediatePointData data) {
			PointHistoryDataModel pointHistoryDataModel = new PointHistoryDataModel();
			MessageTextParseDataModel textDataModel = gmsMsgFile.GetTextDataModel(GetMessageLabelByID(MessageID.TradeDate));
			if (data.sendMonsNo != MonsNo.NULL)
			{
				pointHistoryDataModel.SetPointData(data);
				pointHistoryDataModel.SetMonsName(CreateMonsNameStr(data.receiveMonsNo));
				string nickName = MessageHelper.SurroundFontTag(data.receiveMonsNickname.GetInvalidRichText(), data.receiveMonsLanguage);
				pointHistoryDataModel.SetMonsNickname(nickName);
				string parentName = MessageHelper.SurroundFontTag(data.receiveMonsParentName.GetInvalidRichText(), data.receiveMonsParentLanguage);
				pointHistoryDataModel.SetParentName(parentName);
				MessageWordSetHelper.SetDigitWord(0, data.year);
				MessageWordSetHelper.SetDigitWord(1, data.month);
				MessageWordSetHelper.SetDigitWord(2, data.day);
				textDataModel.ApplyFormat(true);
				string dateTimeStr = textDataModel.GetAllText();
				pointHistoryDataModel.SetDateTimeStr(dateTimeStr);
				textDataModel.Dispose();
				pointHistoryDataModel.receiveMonsSexIconSpr = resourceContainer.GetSexSpr(data.receiveMonsSex);
				pointHistoryDataModel.receiveMonsLangIconSpr = resourceContainer.GetLangIconSpr(data.receiveMonsLanguage);
				pointHistoryDataModel.receiveMonsParentLangIconSpr = resourceContainer.GetLangIconSpr(data.receiveMonsParentLanguage);
				LoadMonsIconSpr(data.sendMonsNo, (ushort)data.sendMonsFormNo, data.sendMonsSex, spr => pointHistoryDataModel.sendMonsIconSpr = spr);
				LoadMonsIconSpr(data.receiveMonsNo, data.receiveMonsFormNo, data.receiveMonsSex, spr => pointHistoryDataModel.receiveMonsIconSpr = spr);
			}
			return pointHistoryDataModel;
		}
		private string CreateMonsNameStr(global::Pml.MonsNo monsNo) {
			if (monsNameTable.ContainsKey((int)monsNo))
				return monsNameTable[(int)monsNo];

			MessageGlossaryParseDataModel nameDataModel = monsNameMsgFile.GetNameDataModelByIndex((int)monsNo);
			string monsName = nameDataModel.GetName();
			monsNameTable.Add((int)monsNo, monsName);
			nameDataModel.Dispose();
			return monsName;
		}
		private void LoadMonsIconSpr(global::Pml.MonsNo monsNo, ushort formNo, global::Pml.Sex sex, global::System.Action<global::UnityEngine.Sprite> onLoadComplete) {
			if (!resourceContainer.CheckHasMonsIcon(monsNo, formNo))
			{
				uiManagerPtr.LoadSpritePokemon(monsNo, formNo, sex, Pml.PokePara.RareType.NOT_RARE, false, spr =>
				{
					resourceContainer.AddMonsIconSpr(monsNo, formNo, spr);
					onLoadComplete?.Invoke(spr);
				});
				return;
			}
			Sprite iconSpr = resourceContainer.GetMonsIconSpr(monsNo, formNo);
			onLoadComplete?.Invoke(iconSpr);
		}
		public global::Dpr.GMS.GMSPointDataModel FindNearPointDataFromCamera(ref global::UnityEngine.Vector3 cameraNormal) {
			GMSPointDataModel[] pointDatas = dataContainer.PointDatas;
			GMSPointDataModel nearPointData = null;
			float nearDot = 0f;
			for (int i = 0; i < pointDatas.Length; i++)
			{
				GMSPointDataModel pointData = pointDatas[i];
				if (pointData == null)
					continue;
				if (selectGMSMode == GMSMode.Browsing && !pointData.HasData)
					continue;

				float dot = SmartPoint.Mathematics.FastMath.Dot(-cameraNormal, pointData.Normal);
				if (nearPointData == null || (dot <= 0f && dot < nearDot))
				{
					nearPointData = pointData;
					nearDot = dot;
				}
			}
			if (nearPointData != null)
				GMSWork.EmitLog(string.Format("Find Near Point Index : {0}", nearPointData.index));
			return nearPointData;
		}
		public void MarkHistoryData(int pointIndex, int dataIndex, bool isSave) {
			GMSPointDataModel pointData = GetPointDataModelByIndex(pointIndex);
			pointData.ChangeMarkHistoryData(dataIndex);
			if (isSave)
				GMSWork.ApplyAllPointData(pointData);
		}
		public void AddHistoryData(int pointIndex, global::Dpr.GMS.IntermediatePointData newData, bool isNew, bool isSave) {
			GMSPointDataModel pointData = GetPointDataModelByIndex(pointIndex);
			PointHistoryDataModel newHistoryData = CreateHistoryDataModel(newData);
			newHistoryData.SetNewFlag(isNew);
			int dataIndex = pointData.DataCount;
			pointData.AddHistoryData(newHistoryData);
			lastUpdatePointData = pointData;
			ResetData();
			if (isSave)
				GMSWork.ApplyPointData(newHistoryData, pointIndex, dataIndex);
		}
		public void InsertHistoryData(int pointIndex, global::Dpr.GMS.IntermediatePointData newData, bool isMark, bool isNew, bool isSave) {
			GMSWork.EmitLog(string.Format("Insert Data : PointIndex[{0}] - Mark[{1}] - New [{2}] - Save [{3}]", pointIndex, isMark, isNew, isSave));
			AddHistoryData(pointIndex, newData, isNew, false);
			if (isMark)
			{
				GMSPointDataModel pointData = GetPointDataModelByIndex(pointIndex);
				pointData.ChangeMarkHistoryData(pointData.DataCount - 1);
				if (isSave)
					GMSWork.ApplyAllPointData(pointData);
			}
		}
		public void DeleteHistoryData(int pointIndex, int dataIndex, bool isSave) {
			GMSPointDataModel pointData = GetPointDataModelByIndex(pointIndex);
			pointData.DeleteHistoryData(dataIndex);
			pointData.SortHistoryData();
			ResetData();
			if (isSave)
				GMSWork.ApplyAllPointData(pointData);
		}
