		public void UpdatePointPosition(global::Dpr.GMS.GMSPointDataModel target, in global::UnityEngine.Vector3 cameraNormal, bool isMaxZoom) {
			if (IsViewCamera(target, cameraNormal, isMaxZoom))
			{
				Vector2 screenPos = mainCameraPtr.WorldToViewportPoint(target.point);
				screenPos.x = screenPos.x * SCREE_SIZE.x - SCREE_SIZE.x * 0.5f;
				screenPos.y = screenPos.y * SCREE_SIZE.y - SCREE_SIZE.y * 0.5f;
				target.ChangeViewStatus(true);
				target.SetScreenPosition(screenPos);
			}
			else
			{
				target.ChangeViewStatus(false);
			}
		}
		private bool IsViewCamera(global::Dpr.GMS.GMSPointDataModel target, in global::UnityEngine.Vector3 cameraNormal, bool isMaxZoom) {
			if (selectGMSMode == GMSMode.Browsing && !isMaxZoom && !target.HasData)
				return false;
			if (SmartPoint.Mathematics.FastMath.Dot(target.Normal, cameraNormal) < showPointDotValue)
				return false;

			return VIEWPORT_RECT.Contains(mainCameraPtr.WorldToViewportPoint(target.point));
		}
