		public void OpenBoxWindow(global::System.Action onSelectMons, global::System.Action onCancel) {
			CloseKeyguide();
			selectBoxPokemon = null;
			ResetFaderParam();
			BoxWindow boxWindow = uiManagerPtr.CreateUIWindow<BoxWindow>(UIWindowID.BOX);
			boxWindow.Open(CreateBoxWindowParam(), (window, select) =>
			{
				selectBoxPokemon = select[0];
				Fader.fadeMode = (Fader.FadeMode)0;
				Fader.fillColor = UIWindow.TransitionFadeFillColor;
				Fader.FadeOut(0.1f);
			}, (UIWindowID)(-2));
			boxWindow.onClosed = __ =>
			{
				if (selectBoxPokemon != null)
				{
					Fader.FadeIn(0.1f);
					OpenKeyguide(KeyguidePattern.Trade);
					onSelectMons?.Invoke();
				}
				else
				{
					onCancel?.Invoke();
				}
			};
		}
		private global::Dpr.UI.BoxWindow.OpenParam CreateBoxWindowParam() {
			BoxWindow.OpenParam param = new BoxWindow.OpenParam();
			param.selectCount = 1;
			param.isEnableEgg = false;
			param.isEnableTeam = false;
			param.selectNgPokeNos = ngPokeNos;
			param.isDontDuckOffBGM = true;
			param.isExternalTrade = true;
			param.isGMS = true;
			GMSWork.EmitLog(string.Format("BoxParam : Select[{0}] Dying[{1}] Egg[{2}] Team[{3}] Party[{4}]", param.selectCount, param.isEnableDying, param.isEnableEgg, param.isEnableTeam, param.isEnableParty));
			return param;
		}
