		public int ClampPointIndex(int pointIndex) {
			if (pointIndex < 0)
			{
				GMSWork.EmitLog(string.Format("pointIndex under 0 : [{0}]", pointIndex));
				return 0;
			}
			if (pointIndex >= maxPointNum)
			{
				GMSWork.EmitLog(string.Format("pointIndex over [{0}] : [{1}]", maxPointNum - 1, pointIndex));
				return maxPointNum - 1;
			}
			return pointIndex;
		}
		public void PerformCheckDprIllegalFlag() {
