				? PlayerWork.playerParty.GetMemberPointerConst((uint)selectBoxPokemon.IndexInTray)
				: Dpr.Box.BoxPokemonWork.GetPokemon(selectBoxPokemon.TrayIndex, selectBoxPokemon.IndexInTray);
