		public void SettingSendDataModel(int selectPointIndex) {
			GMSWork.EmitLog(string.Format("Send PointIndex[{0}]", selectPointIndex));
			if (tradeResultData == null)
				tradeResultData = new TradeResultData();

			SendMonsDataModel sendData = tradeResultData.sendData;
			sendData.Clear();
			sendData.pointIndex = selectPointIndex;
			Pml.PokePara.PokemonParam pokeParam = new Pml.PokePara.PokemonParam();
			pokeParam.CopyFrom(selectBoxPokemon.Param);
			PokeWork.ChangeLandformSheimi(pokeParam);
			sendData.CreateDemoPokeParam(pokeParam.GetCoreData());
			sendData.sendMonsNo = pokeParam.GetMonsNo();
			sendData.sendMonsFormNo = pokeParam.GetFormNo();
			sendData.sendMonsSex = pokeParam.GetSex();
			pokeParam.SetNickName(Utils.CheckNGPokeName(pokeParam));
			string parentName = pokeParam.GetParentName();
			parentName = Utils.CheckNGTrainerName(ref parentName, (MessageEnumData.MsgLangId)pokeParam.GetLangId());
			pokeParam.SetParentName(parentName);
			string pastParentsName = pokeParam.GetPastParentsName();
			if (!string.IsNullOrEmpty(pastParentsName))
				pokeParam.SetPastParentsName(Utils.CheckNGTrainerName(ref pastParentsName, (MessageEnumData.MsgLangId)pokeParam.GetPastParentsLangID()));
			sendData.selectPokeParam = pokeParam;
			sendData.trayIndex = selectBoxPokemon.TrayIndex;
			sendData.indexInTray = selectBoxPokemon.IndexInTray;
			selectBoxPokemon = null;
		}
		public void OnReceivePokeData(int pointNo, byte[] coreData) {
			tradeDemoParam = new Demo_Trade();
			tradeDemoParam.isDisableMainCamera = false;
			tradeResultData.receiveData.pointIndex = pointNo;
			Pml.PokePara.PokemonParam pokeParam = new Pml.PokePara.PokemonParam();
			pokeParam.Deserialize_Core(coreData);
			uint langId = pokeParam.GetLangId();
			pokeParam.SetNickName(Utils.CheckNGPokeName(pokeParam));
			string parentName = pokeParam.GetParentName();
			parentName = Utils.CheckNGTrainerName(ref parentName, (MessageEnumData.MsgLangId)langId);
			pokeParam.SetParentName(parentName);
			string pastParentsName = pokeParam.GetPastParentsName();
			if (string.IsNullOrEmpty(pastParentsName))
			{
				tradeResultData.parentName = pokeParam.GetParentName();
			}
			else
			{
				langId = pokeParam.GetPastParentsLangID();
				tradeResultData.parentName = Utils.CheckNGTrainerName(ref pastParentsName, (MessageEnumData.MsgLangId)langId);
			}
			tradeResultData.parentLangId = (MessageEnumData.MsgLangId)langId;
			pokeParam.UpdateOwnerInfo(new Pml.PokePara.OwnerInfo(PlayerWork.playerStatus));
			uint cassetteVersion = pokeParam.GetCassetteVersion();
			if ((cassetteVersion == CassetVersion.DPR_B || cassetteVersion == CassetVersion.DPR_S) && pokeParam.GetMemories(Pml.PokePara.Memories.EGG_TAKEN_PLACE) == 0)
				pokeParam.SetMemories(Pml.PokePara.Memories.EGG_TAKEN_PLACE, 0xffff);

			Pml.PokePara.PokemonParam receivePokeParam = new Pml.PokePara.PokemonParam();
			receivePokeParam.CopyFrom(pokeParam);
			tradeDemoParam.IsGetMonsNo = ZukanWork.IsGet((uint)pokeParam.GetMonsNo());
			ZukanWork.SetPoke(pokeParam, GET_STATUS.GET);

			SendMonsDataModel sendData = tradeResultData.sendData;
			PokeParty party = PlayerWork.playerParty;
			MonsNo nextMonsNo = MonsNo.NULL;
			uint routeIndex = 0;
			int trayIndex = sendData.trayIndex;
			if (trayIndex < 0)
			{
				party.AddMember(pokeParam);
				uint lastIndex = party.GetMemberCount() - 1;
				if (sendData.indexInTray != lastIndex)
				{
					for (int i = (int)lastIndex; i > sendData.indexInTray; i--)
						PlayerWork.playerParty.ExchangePosition((byte)i, (byte)(i - 1));
				}
				Dpr.BallDeco.BallDecoWork.RemoveAttachCapsule(-1, sendData.indexInTray);
			}
			else
			{
				Dpr.Box.BoxPokemonWork.UpdatePokemon(pokeParam, trayIndex, sendData.indexInTray);
				Dpr.BallDeco.BallDecoWork.RemoveAttachCapsule(sendData.trayIndex, sendData.indexInTray);
			}

			evolvedTargetPokeParam.pokeParam = null;
			evolvedTargetPokeParam.isTeam = false;
			evolvedTargetPokeParam.teamIndex = -1;
			evolvedTargetPokeParam.teamPos = -1;
			if (pokeParam.CanEvolveByTrade(pokeParam, ref nextMonsNo, ref routeIndex))
			{
				Pml.PokePara.PokemonParam evolvePokeParam = trayIndex < 0
					? party.GetMemberPointer((uint)sendData.indexInTray)
					: Dpr.Box.BoxPokemonWork.GetPokemon(sendData.trayIndex, sendData.indexInTray);
				evolvePokeParam.Evolve(nextMonsNo, routeIndex);
				tradeDemoParam.IsGetEvolvedMonsNo = ZukanWork.IsGet((uint)nextMonsNo);
				evolvedTargetPokeParam.pokeParam = evolvePokeParam;
				evolvedTargetPokeParam.isTeam = trayIndex < 0;
				evolvedTargetPokeParam.teamIndex = sendData.trayIndex;
				evolvedTargetPokeParam.teamPos = sendData.indexInTray;
				tradeDemoParam.FriendPokeParam = evolvedTargetPokeParam;
				if (trayIndex >= 0)
					Dpr.Box.BoxPokemonWork.UpdatePokemon(evolvePokeParam, sendData.trayIndex, sendData.indexInTray);
				ZukanWork.SetPoke(evolvePokeParam, GET_STATUS.GET);
			}

			DateTime nowTime = GameManager.nowTime;
			tradeResultData.year = nowTime.Year;
			tradeResultData.month = (byte)nowTime.Month;
			tradeResultData.day = (byte)nowTime.Day;
			tradeResultData.receiveData.pokeParam = receivePokeParam;
			tradeResultData.receiveData.coreData = receivePokeParam.GetCoreData();
		}
		public void ApplyDemoParam() {
			tradeDemoParam.MyPokeParam_Copy = tradeResultData.sendData.demoPokeParam;
			tradeDemoParam.FriendPokeParam_Copy = tradeResultData.receiveData.pokeParam;
			tradeDemoParam.SetParam((int)PlayerWork.playerStatus.id, (int)tradeDemoParam.FriendPokeParam_Copy.GetID(), tradeResultData.parentName, true, tradeResultData.parentLangId);
		}
		public void DeleteSendPokeData() {
			SendMonsDataModel sendData = tradeResultData.sendData;
			if (sendData.selectPokeParam == null)
				return;

			if (sendData.trayIndex < 0)
				PlayerWork.playerParty.RemoveMember((uint)sendData.indexInTray);
			else
				Dpr.Box.BoxPokemonWork.ClearPokemon(sendData.trayIndex, sendData.indexInTray);
			tradeResultData.sendData.CopySendCoreData(sendData.selectPokeParam.GetCoreData());
			sendData.selectPokeParam.Clear();
		}
