		public bool CheckPutRankup() {
			if (lockCheckAchievementFlag)
				return false;
			if (IsRankMax)
				return false;

			GMSMasterData.SheetPutRank rankData = gmsMasterData.PutRank[achievementStep];
			if (rankData.nextRankCount > nowTotalPutPointNum)
				return false;

			GMSWork.EmitLog(string.Format("RankUp[{0}] : [{1}]/[{2}]", achievementStep, nowTotalPutPointNum, rankData.nextRankCount));
			lockCheckAchievementFlag = true;
			return true;
		}
		public global::Dpr.GMS.AchievementInfo AchievementStepUp() {
			achievementInfo.Clear();
			GMSMasterData.SheetPutRank rankData = gmsMasterData.PutRank[achievementStep];
			hasAchievementReward = (ItemNo)rankData.rewardItemNo != ItemNo.DUMMY_DATA && rankData.rewardNum > 0;
			if (hasAchievementReward)
			{
				MessageWordSetHelper.SetItemWord(0, rankData.rewardItemNo, rankData.rewardNum);
				MessageWordSetHelper.SetDigitWord(1, rankData.rewardNum);
				GMSWork.AddReward(rankData.rewardItemNo, rankData.rewardNum);
			}
			achievementStep++;
			GMSWork.EmitLog(string.Format("RankUp[{0}]", achievementStep));
			achievementInfo.SetTitleSpr(GetSpriteByIndex(rankData.texIndex));
			achievementInfo.SetRankData(rankData);
			return achievementInfo;
		}
