		public void OpenKeyguide(global::Dpr.GMS.KeyguidePattern pattern) {
			if (keyguide == null)
			{
				keyguide = uiManagerPtr.GetKeyguide(null, true);
				keyguide.transform.SetParent(keyGuideParent, false);
			}
			else
			{
				if (keyguidePattern == pattern)
					return;

				keyguidePattern = pattern;
			}

			Keyguide.Param param = null;
			switch (pattern)
			{
				case KeyguidePattern.Top:
					param = CreateKeyguidePatternTop();
					break;
				case KeyguidePattern.Trade:
					param = CreateKeyguidePatternTrade();
					break;
				case KeyguidePattern.TradeHistory:
					param = CreateKeyguidePatternTradeHistory();
					break;
				case KeyguidePattern.Browsing:
					param = CreateKeyguidePatternBrowsing();
					break;
				case KeyguidePattern.BrowsingHistory:
					param = CreateKeyguidePatternBrowsingHistory();
					break;
				case KeyguidePattern.Decide:
					// Shipped: the Decide param is built and dropped — Open receives null (@01c9ad98 `mov x20, xzr`).
					CreateKeyguidePatternDecide();
					break;
				case KeyguidePattern.Empty:
					param = CreateKeyguidePatternEmpty();
					break;
			}
			keyguide.gameObject.SetActive(true);
			keyguide.Open(param);
		}
		private global::Dpr.UI.Keyguide.Param CreateKeyguidePatternTop() {
			Keyguide.Param param = new Keyguide.Param();
			param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.GMSTATION_VIEW_DECIDE });
			param.itemParams.Add(new KeyguideItem.Param() { keyguideId = KeyguideID.GMSTATION_CANCEL });
			return param;
		}
